CREATE OR REPLACE FUNCTION public.set_reservation_deadline()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_channel text;
begin
  -- An explicitly supplied deadline always wins; this only fills the gap.
  if new.expires_at is not null then
    return new;
  end if;

  select o.channel_source into v_channel
  from public.order_requests o where o.id = new.order_request_id;

  -- Marketplace orders are fulfilled against the platform's own commitment, and
  -- Pasabuy/wholesale hold nothing. Only direct website purchases take a timed
  -- hold. An unknown channel is left without a deadline rather than given one:
  -- a wrongly applied deadline silently cancels a real customer's hold.
  if v_channel is distinct from 'website' then
    return new;
  end if;

  new.hold_minutes := coalesce(new.hold_minutes, 30);
  new.expires_at := now() + make_interval(mins => new.hold_minutes);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION k2_private.guard_order_delivery_items_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_op='TRUNCATE' then
  if exists(select 1 from public.order_requests o where o.channel_source='website'
   and not exists(select 1 from k2_private.order_delivery_snapshots s where s.order_id=o.id)) then
   raise exception using errcode='22023',message='K2_DELIVERY_REVIEW_REQUIRED';
  end if;
 elsif (tg_op in ('UPDATE','DELETE') and exists(select 1 from public.order_requests o
  where o.id=old.order_request_id and o.channel_source='website'
   and not exists(select 1 from k2_private.order_delivery_snapshots s where s.order_id=o.id)))
  or (tg_op='UPDATE' and exists(select 1 from public.order_requests o
   where o.id=new.order_request_id and o.channel_source='website'
    and not exists(select 1 from k2_private.order_delivery_snapshots s where s.order_id=o.id))) then
  raise exception using errcode='22023',message='K2_DELIVERY_REVIEW_REQUIRED';
 end if;
 if tg_op='TRUNCATE' then
  if exists(select 1 from k2_private.order_delivery_snapshots) then raise exception using errcode='22023',message='K2_ORDER_CHARGE_IMMUTABLE';end if;
  return null;
 end if;
 if (tg_op in ('UPDATE','DELETE') and exists(select 1 from k2_private.order_delivery_snapshots where order_id=old.order_request_id))
  or (tg_op in ('INSERT','UPDATE') and exists(select 1 from k2_private.order_delivery_snapshots where order_id=new.order_request_id)) then
  raise exception using errcode='22023',message='K2_ORDER_CHARGE_IMMUTABLE';
 end if;
 if tg_op='DELETE' then return old;end if;return new;
end $function$

