CREATE OR REPLACE FUNCTION k2_private.current_category_lot_context_v1()
 RETURNS k2_private.category_lot_command_context
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_context k2_private.category_lot_command_context;
begin
 select * into v_context from k2_private.category_lot_command_context
  where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id();
 if not found then raise exception using errcode='55000',message='K2_CATEGORY_CONTEXT_REQUIRED';end if;
 if v_context.actor_id is distinct from auth.uid() then
  raise exception using errcode='42501',message='K2_CATEGORY_CONTEXT_ACTOR_MISMATCH';
 end if;
 if v_context.authority_kind='guest' then
  if not exists(select 1 from k2_private.guest_request_nonces n
  where n.action='order' and n.nonce=v_context.guest_nonce
   and n.verified_backend_pid=pg_catalog.pg_backend_pid()
   and n.verified_transaction_id=pg_catalog.pg_current_xact_id()
   and n.expires_at>pg_catalog.clock_timestamp()) then
   raise exception using errcode='42501',message='K2_GUEST_CONTEXT_PROOF_REQUIRED';
  end if;
 elsif v_context.authority_kind='staff' then
  if not public.is_staff() then raise exception using errcode='42501',message='K2_STAFF_REQUIRED';end if;
  if coalesce(auth.jwt()->>'aal','')<>'aal2' then raise exception using errcode='42501',message='K2_AAL2_REQUIRED';end if;
 else
  raise exception using errcode='42501',message='K2_CATEGORY_CONTEXT_AUTHORITY_INVALID';
 end if;
 return v_context;
end $function$

CREATE OR REPLACE FUNCTION k2_private.effective_category_minimum_v1(p_category_id uuid, p_max_depth integer)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_current uuid:=p_category_id;
 v_parent uuid;
 v_override integer;
 v_visited uuid[]:='{}';
 v_minimum integer:=90;
begin
 if p_category_id is null or p_max_depth is null or p_max_depth < 1 then return null; end if;
 while v_current is not null loop
  if v_current=any(v_visited) or pg_catalog.cardinality(v_visited)>=p_max_depth then return null; end if;
  select c.parent_id,p.minimum_days into v_parent,v_override
   from public.categories c left join k2_private.category_shelf_life_policy p on p.category_id=c.id
   where c.id=v_current;
  if not found then return null; end if;
  if v_override is not null and v_override < 90 then return null; end if;
  v_minimum:=greatest(v_minimum,coalesce(v_override,90));
  v_visited:=pg_catalog.array_append(v_visited,v_current);
  v_current:=v_parent;
 end loop;
 return v_minimum;
end $function$

CREATE OR REPLACE FUNCTION k2_private.lock_category_policy_v1(p_exclusive boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_namespace integer:=1261585232;
 v_resource integer:=1347374169;
 v_shared boolean;
 v_exclusive boolean;
 v_lock_timeout interval;
 v_statement_timeout interval;
begin
 if p_exclusive is null then
  raise exception using errcode='22023',message='K2_CATEGORY_POLICY_MODE_REQUIRED';
 end if;
 if pg_catalog.current_setting('transaction_isolation')<>'read committed' then
  raise exception using errcode='0A000',message='K2_CATEGORY_POLICY_ISOLATION_UNSUPPORTED';
 end if;
 v_lock_timeout:=pg_catalog.current_setting('lock_timeout')::interval;
 v_statement_timeout:=pg_catalog.current_setting('statement_timeout')::interval;
 if v_lock_timeout<=interval '0' or v_lock_timeout>interval '2 seconds'
    or v_statement_timeout<=interval '0' or v_statement_timeout>interval '10 seconds' then
  raise exception using errcode='55000',message='K2_CATEGORY_POLICY_DEADLINES_REQUIRED';
 end if;
 select coalesce(pg_catalog.bool_or(l.mode='ShareLock'),false),
        coalesce(pg_catalog.bool_or(l.mode='ExclusiveLock'),false)
  into v_shared,v_exclusive from pg_catalog.pg_locks l
  where l.locktype='advisory' and l.pid=pg_catalog.pg_backend_pid()
    and l.classid=v_namespace::oid and l.objid=v_resource::oid
    and l.objsubid=2 and l.granted;
 if v_exclusive then return; end if;
 if v_shared then
  if p_exclusive then
   raise exception using errcode='55000',message='K2_CATEGORY_POLICY_UPGRADE_REFUSED';
  end if;
  return;
 end if;
 if p_exclusive then
  perform pg_catalog.pg_advisory_xact_lock(v_namespace,v_resource);
 else
  perform pg_catalog.pg_advisory_xact_lock_shared(v_namespace,v_resource);
 end if;
end $function$

CREATE OR REPLACE FUNCTION k2_private.lot_is_eligible_for_category_v1(p_lot product_batches, p_max_depth integer, p_evaluation_instant timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_category uuid;
 v_minimum integer;
 v_expiry date:=coalesce(p_lot.expiry_date,p_lot.best_before_date);
 v_today date;
 v_days numeric;
begin
 if p_evaluation_instant is null or not pg_catalog.isfinite(p_evaluation_instant)
    or v_expiry is null or not pg_catalog.isfinite(v_expiry) then return false; end if;
 -- A finite timestamp near the type limit can still overflow during timezone conversion.
 begin
  v_today:=(p_evaluation_instant at time zone 'Asia/Manila')::date;
 exception when datetime_field_overflow then return false;
 end;
 select p.category_id into v_category from public.products p where p.sku=p_lot.sku;
 if not found or v_category is null then return false; end if;
 v_minimum:=k2_private.effective_category_minimum_v1(v_category,p_max_depth);
 if v_minimum is null then return false; end if;
 -- Each finite date's epoch offset fits int; widen BEFORE subtracting offsets.
 -- This avoids adding a potentially int-max policy minimum to a near-limit date.
 v_days:=(v_expiry-date '2000-01-01')::numeric-(v_today-date '2000-01-01')::numeric;
 return exists (
  select 1 from public.hubs h
  join public.custodians c on c.id=p_lot.custodian and c.hub_id=h.id
  where h.id=p_lot.hub and h.id='HUB-MNL-CENTRAL' and h.country='PH'
   and p_lot.inventory_status='available' and p_lot.quantity>0
   and p_lot.reserved_quantity>=0 and p_lot.reserved_quantity<=p_lot.quantity
   and (
    v_days>=v_minimum
    or (
     v_days between 31 and 89
     and p_lot.clearance_approved_at is not null and p_lot.clearance_approved_by is not null
     and p_lot.clearance_approved_at<=p_evaluation_instant
     and exists (
      select 1 from public.batch_change_events e
      where e.batch_id=p_lot.id and e.sku=p_lot.sku and e.actor_id=p_lot.clearance_approved_by
       and nullif(pg_catalog.btrim(e.reason),'') is not null
       -- Preserve both supported approval writers and same-instant marker/event evidence.
       and e.created_at=p_lot.clearance_approved_at and e.created_at<=p_evaluation_instant
       and coalesce(e.new_data->>'expiry_date',e.new_data->>'best_before_date')=v_expiry::text
       and (
        e.new_data->'clearance_approved'='true'::jsonb
        or (e.new_data->>'clearance_approved_by'=p_lot.clearance_approved_by::text
         and case when pg_catalog.pg_input_is_valid(
          e.new_data->>'clearance_approved_at','timestamp with time zone')
          then (e.new_data->>'clearance_approved_at')::timestamptz end=p_lot.clearance_approved_at
         and e.old_data->'clearance_approved_at' is distinct from e.new_data->'clearance_approved_at')
       )
       and not exists (
        select 1 from public.batch_change_events x
        where x.batch_id=p_lot.id and x.sku=p_lot.sku and x.id<>e.id
         and x.created_at>=p_lot.clearance_approved_at and x.created_at<=p_evaluation_instant
         and (
          x.new_data->'clearance_approved'='false'::jsonb
          or (x.new_data ? 'inventory_status' and (
           x.new_data->>'inventory_status' is distinct from 'available'
           or x.old_data->'expiry_date' is distinct from x.new_data->'expiry_date'
           or x.old_data->'best_before_date' is distinct from x.new_data->'best_before_date'
          ))
         )
       )
     )
    )
   )
 );
end $function$

CREATE OR REPLACE FUNCTION k2_private.start_category_lot_context_v1(p_maximum_depth integer)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_instant timestamptz;
begin
 if p_maximum_depth is null or p_maximum_depth<1 then
  raise exception using errcode='22023',message='K2_CATEGORY_CONTEXT_INPUT_INVALID';
 end if;
 if auth.uid() is null or not public.is_staff() then
  raise exception using errcode='42501',message='K2_STAFF_REQUIRED';
 end if;
 if coalesce(auth.jwt()->>'aal','')<>'aal2' then
  raise exception using errcode='42501',message='K2_AAL2_REQUIRED';
 end if;
 -- Verify an existing boundary; never acquire a late policy lock here.
 if not exists(select 1 from pg_catalog.pg_locks l where l.pid=pg_catalog.pg_backend_pid()
  and l.locktype='advisory' and l.classid=1261585232::oid and l.objid=1347374169::oid
  and l.objsubid=2 and l.granted and l.mode in ('ShareLock','ExclusiveLock')) then
  raise exception using errcode='55000',message='K2_CATEGORY_CONTEXT_ENTRY_REQUIRED';
 end if;
 if exists(select 1 from k2_private.category_lot_command_context
  where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then
  raise exception using errcode='55000',message='K2_CATEGORY_CONTEXT_ALREADY_SET';
 end if;
 v_instant:=pg_catalog.clock_timestamp();
 insert into k2_private.category_lot_command_context
 (backend_pid,transaction_id,actor_id,maximum_depth,evaluation_instant,authority_kind,guest_nonce)
 values(pg_catalog.pg_backend_pid(),pg_catalog.pg_current_xact_id(),auth.uid(),p_maximum_depth,v_instant,'staff',null);
 return v_instant;
end $function$

CREATE OR REPLACE FUNCTION k2_private.verify_admin_bff_request(p_action text, p_timestamp bigint, p_nonce uuid, p_idempotency_key uuid, p_payload_text text, p_signature text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_secret bytea;
  v_payload_hash text;
  v_expected text;
  v_message text;
  v_bucket_start timestamptz;
  v_actor_hits integer;
  v_global_hits integer;
begin
  if v_actor is null or not public.is_staff() then
    raise exception using errcode='42501',message='K2_ADMIN_ACCESS_REQUIRED';
  end if;
  if coalesce(auth.jwt()->>'aal','')<>'aal2' then
    raise exception using errcode='42501',message='K2_ADMIN_AAL2_REQUIRED';
  end if;
  if p_action is null or p_timestamp is null or p_nonce is null
     or p_idempotency_key is null or p_payload_text is null or p_signature is null then
    raise exception using errcode='22023',message='K2_ADMIN_REQUEST_INVALID';
  end if;
  if p_action not in ('reference_create','cancel_order','delivery_express_quote','delivery_customer_rates_publish',
    'confirm_order', 'packing_scan', 'payment_status', 'delivery_details',
    'fulfill_order', 'transfer_lot', 'assign_box',
    'inbox_internal_note', 'inbox_mark_read', 'inbox_workflow',
    'pasabuy_transition', 'pasabuy_quote',
    'intake_session_create', 'intake_session_step', 'intake_draft',
    'intake_inventory', 'intake_publication', 'intake_evidence_register',
    'consignment_create', 'consignment_add_line', 'consignment_scan',
    'consignment_advance', 'consignment_finalize',
    'lots_reconcile', 'lot_clearance',
    'coupon_create', 'coupon_state', 'coupon_archive',
    'admin_session_register', 'admin_session_validate',
    'admin_session_revoke_current', 'admin_session_revoke_one', 'admin_session_revoke_all',
    'admin_session_list',
    'catalog_import_chunk',
    'wholesale_inquiry_review',
    'admin_mfa_replacement_requested', 'admin_mfa_replacement_completed',
    'product_media_upload', 'product_media_assign', 'product_media_cleanup_complete',
    'product_media_orphan_cleanup', 'product_media_orphan_cleanup_complete',
    'globe_config_update', 'review_create', 'review_update', 'review_publish', 'review_withdraw',
    'supplier_create',
    'channel_internal_event_verify', 'website_listing_set',
    'staff_role_change', 'admin_delete_pin_set',
    'product_master_update', 'product_master_status', 'product_master_delete',
    'category_policy_set', 'category_policy_clear',
    'inbox_send_reply', 'product_knowledge_save', 'product_family_save',
    'ai_spend_controls_update'
  ) then
    raise exception using errcode='22023',message='K2_ADMIN_ACTION_INVALID';
  end if;
  if p_payload_text is null or octet_length(convert_to(p_payload_text, 'UTF8')) >
       (case when p_action='catalog_import_chunk' then 1048576 else 16384 end)
     or p_signature !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='22023',message='K2_ADMIN_REQUEST_INVALID';
  end if;
  if abs(extract(epoch from clock_timestamp())::bigint - p_timestamp)>300 then
    raise exception using errcode='28000',message='K2_ADMIN_SIGNATURE_EXPIRED';
  end if;
  select request_secret into v_secret
  from k2_private.admin_bff_secrets where singleton = true;
  if v_secret is null then
    raise exception using errcode='55000', message='K2_ADMIN_BOUNDARY_NOT_CONFIGURED';
  end if;

  v_payload_hash := encode(extensions.digest(convert_to(p_payload_text, 'UTF8'), 'sha256'), 'hex');
  v_message := p_action || E'\n' || p_timestamp::text || E'\n' || p_nonce::text
    || E'\n' || v_actor::text || E'\n' || p_idempotency_key::text || E'\n' || v_payload_hash;
  v_expected := encode(extensions.hmac(convert_to(v_message, 'UTF8'), v_secret, 'sha256'), 'hex');
  if extensions.digest(convert_to(v_expected, 'UTF8'), 'sha256')
     <> extensions.digest(convert_to(p_signature, 'UTF8'), 'sha256') then
    raise exception using errcode='28000', message='K2_ADMIN_SIGNATURE_INVALID';
  end if;

  v_bucket_start := date_trunc('minute', clock_timestamp());
  delete from k2_private.admin_request_rate_buckets
  where bucket_start < v_bucket_start - interval '1 day';
  insert into k2_private.admin_request_rate_buckets(scope, subject, bucket_start, hit_count)
  values ('actor', v_actor::text, v_bucket_start, 1)
  on conflict (scope, subject, bucket_start) do update
    set hit_count = k2_private.admin_request_rate_buckets.hit_count + 1
  returning hit_count into v_actor_hits;
  if v_actor_hits > 360 then
    raise exception using errcode='54000', message='K2_ADMIN_RATE_LIMITED';
  end if;
  insert into k2_private.admin_request_rate_buckets(scope, subject, bucket_start, hit_count)
  values ('global', 'all_admin_requests', v_bucket_start, 1)
  on conflict (scope, subject, bucket_start) do update
    set hit_count = k2_private.admin_request_rate_buckets.hit_count + 1
  returning hit_count into v_global_hits;
  if v_global_hits > 6000 then
    raise exception using errcode='54000', message='K2_ADMIN_RATE_LIMITED';
  end if;

  delete from k2_private.admin_request_nonces where expires_at<=now();
  insert into k2_private.admin_request_nonces(actor_id,action,nonce,expires_at,verified_backend_pid,verified_transaction_id)
  values(v_actor,p_action,p_nonce,now()+interval '10 minutes',pg_backend_pid(),pg_current_xact_id()) on conflict do nothing;
  return found;
end;
$function$

CREATE OR REPLACE FUNCTION public.commit_order_request_stock_v1(p_order_request_id uuid, p_cause text, p_reason text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_k2_context k2_private.category_lot_command_context;
  v_k2_owned boolean:=false;
  v_k2_depth integer;
  v_k2_instant timestamptz;

  v_res record;
  v_committed integer := 0;
begin
  v_k2_context:=k2_private.current_category_lot_context_v1();
  v_k2_instant:=v_k2_context.evaluation_instant;
  if p_cause is null
     or p_cause not in ('confirmation', 'payment_verification') then
    raise exception 'Unknown stock commitment cause';
  end if;

  -- The order row is locked first, matching cancellation and the sweep, so
  -- a concurrent cancel serializes here instead of racing the allocations.
  perform 1 from public.order_requests where id = p_order_request_id for update;
  if not found then raise exception 'Order request not found'; end if;
  if exists(select 1 from public.order_requests o where o.id=p_order_request_id and o.channel_source='website')
    and not exists(select 1 from k2_private.order_delivery_snapshots where order_id=p_order_request_id) then
    raise exception using errcode='22023',message='K2_DELIVERY_REVIEW_REQUIRED';
  end if;

  for v_res in
    select id, sku, quantity, batch_id
    from public.inventory_reservations
    where order_request_id = p_order_request_id
      and status = 'active'
      and committed_at is null
    order by sku, batch_id, id
    for update
  loop
    update public.inventory_reservations
    set committed_at = v_k2_instant,
        committed_by = auth.uid(),
        commit_reason = nullif(trim(coalesce(p_reason, '')), ''),
        commit_cause = p_cause
    where id = v_res.id;

    -- Physical quantity and encumbered counters are intentionally untouched:
    -- this event deducts ownership, not custody. Handover moves custody.
    insert into public.inventory_events
      (sku, location_code, event_type, quantity, reference_type, reference_id, reason, actor_id, created_at)
    values
      (v_res.sku, 'MANILA_MAIN', 'stock_committed', v_res.quantity,
       'order_request', p_order_request_id,
       'Ownership committed at ' || p_cause || ': '
         || coalesce(nullif(trim(coalesce(p_reason, '')), ''), '(no reason)')
         || '; batch ' || v_res.batch_id::text,
       auth.uid(), v_k2_instant);

    v_committed := v_committed + 1;
  end loop;

  return v_committed;
end;
$function$

CREATE OR REPLACE FUNCTION public.execute_admin_lot_command_v1(p_action text, p_timestamp bigint, p_nonce uuid, p_idempotency_key uuid, p_payload_text text, p_signature text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '2s'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_payload jsonb;
  v_payload_hash text;
  v_receipt k2_private.admin_command_receipts;
  v_lot jsonb;
  v_existing public.product_batches;
  v_saved public.product_batches;
  v_batch_id uuid;
  v_qty integer;
  v_reserved integer;
  v_available integer;
  v_status text;
  v_requested_status text;
  v_expiry date;
  v_clearance_at timestamptz;
  v_clearance_by uuid;
  v_result jsonb;
  v_count integer;
  v_inserted integer;
  v_total integer;
  v_sellable integer;
  v_event_id uuid;
  v_clearance_sku text;
  v_today date;v_instant timestamptz;v_depth integer;
begin
  if not k2_private.verify_admin_bff_request(
    p_action,p_timestamp,p_nonce,p_idempotency_key,p_payload_text,p_signature
  ) then
    raise exception using errcode='28000',message='K2_ADMIN_REQUEST_REPLAYED';
  end if;
  if p_action not in ('lots_reconcile','lot_clearance') then
    raise exception using errcode='22023',message='K2_ADMIN_ACTION_INVALID';
  end if;

  v_payload := p_payload_text::jsonb;
  if jsonb_typeof(v_payload)<>'object' then
    raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
  end if;
  v_payload_hash := encode(extensions.digest(convert_to(p_payload_text,'UTF8'),'sha256'),'hex');

  select * into v_receipt from k2_private.admin_command_receipts
  where actor_id=v_actor and action=p_action and idempotency_key=p_idempotency_key;
  if found then
    if v_receipt.payload_hash<>v_payload_hash then
      raise exception using errcode='22023',message='K2_ADMIN_IDEMPOTENCY_CONFLICT';
    end if;
    if v_receipt.result is null then
      raise exception using errcode='55000',message='K2_ADMIN_COMMAND_IN_PROGRESS';
    end if;
    return v_receipt.result;
  end if;

  select count(*)::integer into v_count from k2_private.admin_command_receipts
  where actor_id=v_actor and action=p_action and created_at>now()-interval '1 minute';
  if v_count>=30 then
    raise exception using errcode='54000',message='K2_ADMIN_RATE_LIMITED';
  end if;
  insert into k2_private.admin_command_receipts(actor_id,action,idempotency_key,payload_hash)
  values(v_actor,p_action,p_idempotency_key,v_payload_hash) on conflict do nothing;
  get diagnostics v_inserted=row_count;
  if v_inserted=0 then
    select * into v_receipt from k2_private.admin_command_receipts
    where actor_id=v_actor and action=p_action and idempotency_key=p_idempotency_key;
    if v_receipt.payload_hash<>v_payload_hash then
      raise exception using errcode='22023',message='K2_ADMIN_IDEMPOTENCY_CONFLICT';
    end if;
    if v_receipt.result is null then
      raise exception using errcode='55000',message='K2_ADMIN_COMMAND_IN_PROGRESS';
    end if;
    return v_receipt.result;
  end if;

  -- Completed durable receipts above retain historical results before new policy checks.
  perform k2_private.lock_category_policy_v1(false);
  select maximum_depth into v_depth from k2_private.category_policy_command_config where singleton;
  if v_depth is null or v_depth<1 then
   raise exception using errcode='55000',message='K2_CATEGORY_POLICY_NOT_CONFIGURED';
  end if;
  if p_action='lots_reconcile' then
    if (v_payload-array['sku','reason','lots'])<>'{}'::jsonb
       or length(trim(coalesce(v_payload->>'sku',''))) not between 1 and 120
       or length(trim(coalesce(v_payload->>'reason',''))) not between 10 and 500
       or jsonb_typeof(v_payload->'lots')<>'array'
       or jsonb_array_length(v_payload->'lots')>50 then
      raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
    end if;
    -- K2_SIGNED_RECOUNT_BALANCE_FIRST_V1
    -- Initialize only from saved physical lots; preserve an existing balance.
    insert into public.inventory_balances(sku,location_code,on_hand,reserved)
    select p.sku,'MANILA_MAIN',coalesce(sum(b.quantity),0)::integer,
      coalesce(sum(b.reserved_quantity),0)::integer
    from public.products p left join public.product_batches b on b.sku=p.sku
    where p.sku=trim(v_payload->>'sku') group by p.sku
    on conflict(sku,location_code) do nothing;
    perform 1 from public.inventory_balances
    where sku=trim(v_payload->>'sku') and location_code='MANILA_MAIN' for update;
    perform 1 from public.products where sku=trim(v_payload->>'sku') for update;
    if not found then
      raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
    end if;

    perform 1 from public.product_batches where sku=trim(v_payload->>'sku') order by id for update;
    if (select k2_private.effective_category_minimum_v1(p.category_id,v_depth)
        from public.products p where p.sku=trim(v_payload->>'sku')) is null then
     raise exception using errcode='23514',message='K2_CATEGORY_POLICY_TAXONOMY_INVALID';
    end if;
    v_instant:=k2_private.start_category_lot_context_v1(v_depth);
    v_today:=(v_instant at time zone 'Asia/Manila')::date;
    for v_lot in select * from jsonb_array_elements(v_payload->'lots') loop
      if jsonb_typeof(v_lot)<>'object'
         or (v_lot-array['id','boxCode','batchCode','quantity','expiryDate','landedDate','hub','custodian','channel','pinned','status'])<>'{}'::jsonb
         or (v_lot->'id' is not null and jsonb_typeof(v_lot->'id')<>'null'
             and coalesce(v_lot->>'id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
         or jsonb_typeof(v_lot->'quantity')<>'number'
         or (v_lot->>'quantity')::numeric<>trunc((v_lot->>'quantity')::numeric)
         or (v_lot->>'quantity')::integer not between 0 and 1000000
         or jsonb_typeof(v_lot->'pinned')<>'boolean'
         or coalesce(v_lot->>'status','') not in ('available','quarantine','damaged','expired','unaccounted','depleted')
         or length(trim(coalesce(v_lot->>'boxCode',''))) > 120
         or length(trim(coalesce(v_lot->>'batchCode',''))) > 120
         or length(trim(coalesce(v_lot->>'hub',''))) > 120
         or length(trim(coalesce(v_lot->>'custodian',''))) > 120
         or length(trim(coalesce(v_lot->>'channel',''))) > 80
         or (nullif(v_lot->>'expiryDate','') is not null and coalesce(v_lot->>'expiryDate','') !~ '^\d{4}-\d{2}-\d{2}$')
         or (nullif(v_lot->>'landedDate','') is not null and coalesce(v_lot->>'landedDate','') !~ '^\d{4}-\d{2}-\d{2}$')
         or (v_lot->>'quantity')::integer>0 and (
           nullif(trim(coalesce(v_lot->>'boxCode','')),'') is null
           or nullif(trim(coalesce(v_lot->>'batchCode','')),'') is null
           or nullif(v_lot->>'expiryDate','') is null
           or nullif(trim(coalesce(v_lot->>'hub','')),'') is null
           or nullif(trim(coalesce(v_lot->>'custodian','')),'') is null
         ) then
        raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
      end if;
      if nullif(v_lot->>'expiryDate','')::date<'2000-01-01'::date
         or nullif(v_lot->>'expiryDate','')::date>v_today+3653
         or nullif(v_lot->>'landedDate','')::date<'2000-01-01'::date
         or nullif(v_lot->>'landedDate','')::date>v_today then
        raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
      end if;
    end loop;

    if exists(
      select 1 from jsonb_array_elements(v_payload->'lots') x
      where nullif(x->>'id','') is not null
      group by x->>'id' having count(*)>1
    ) or exists(
      select 1 from public.product_batches b where b.sku=trim(v_payload->>'sku')
      and not exists(select 1 from jsonb_array_elements(v_payload->'lots') x where x->>'id'=b.id::text)
    ) then
      raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
    end if;

    v_count:=0;
    for v_lot in select * from jsonb_array_elements(v_payload->'lots') loop
      v_batch_id:=nullif(v_lot->>'id','')::uuid;
      v_qty:=(v_lot->>'quantity')::integer;
      v_expiry:=nullif(v_lot->>'expiryDate','')::date;
      v_requested_status:=v_lot->>'status';
      v_reserved:=0;
      v_clearance_at:=null;
      v_clearance_by:=null;

      if v_batch_id is not null then
        select * into v_existing from public.product_batches
        where id=v_batch_id and sku=trim(v_payload->>'sku') for update;
        if not found then
          raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
        end if;
        v_reserved:=coalesce(v_existing.reserved_quantity,0);
        if v_qty<v_reserved then
          raise exception using errcode='23514',message='K2_LOT_RESERVED_CONFLICT';
        end if;
        v_clearance_at:=v_existing.clearance_approved_at;
        v_clearance_by:=v_existing.clearance_approved_by;
        if v_existing.expiry_date is distinct from v_expiry or v_requested_status<>'available' then
          v_clearance_at:=null;
          v_clearance_by:=null;
        end if;
      end if;

      v_status:=case
        when v_qty=0 then 'depleted'
        when v_expiry<v_today then 'expired'
        when v_expiry<=v_today+30 then 'quarantine'
        when v_requested_status='available' and v_expiry between v_today+31 and v_today+89
             and v_clearance_at is null then 'quarantine'
        else v_requested_status end;
      v_available:=case when v_status='available' and (
        v_expiry>=v_today+90 or
        (v_expiry between v_today+31 and v_today+89 and v_clearance_at is not null)
      ) then greatest(v_qty-v_reserved,0) else 0 end;

      if v_batch_id is null then
        insert into public.product_batches(
          sku,box_code,batch_code,quantity,quantity_available,reserved_quantity,
          expiry_date,best_before_date,landed_date,hub,custodian,channel,is_pinned,
          inventory_status,clearance_approved_at,clearance_approved_by,updated_at
        ) values(
          trim(v_payload->>'sku'),nullif(trim(v_lot->>'boxCode'),''),nullif(trim(v_lot->>'batchCode'),''),
          v_qty,v_available,0,v_expiry,v_expiry,coalesce(nullif(v_lot->>'landedDate','')::date,v_today),
          nullif(trim(v_lot->>'hub'),''),nullif(trim(v_lot->>'custodian'),''),nullif(trim(v_lot->>'channel'),''),
          (v_lot->>'pinned')::boolean,v_status,null,null,now()
        ) returning * into v_saved;
        insert into public.batch_change_events(batch_id,sku,reason,old_data,new_data,actor_id,created_at)
        values(v_saved.id,v_saved.sku,trim(v_payload->>'reason'),null,to_jsonb(v_saved),v_actor,v_instant) returning id into v_event_id;
    -- The approval/history event now exists. Finalize only this command's event.
    update public.product_batches set quantity_available=quantity_available
    where id=v_saved.id returning * into v_saved;
    update public.batch_change_events set new_data=to_jsonb(v_saved)
    where id=v_event_id;
      else
        update public.product_batches set
          box_code=nullif(trim(v_lot->>'boxCode'),''),batch_code=nullif(trim(v_lot->>'batchCode'),''),
          quantity=v_qty,quantity_available=v_available,expiry_date=v_expiry,best_before_date=v_expiry,
          landed_date=coalesce(nullif(v_lot->>'landedDate','')::date,landed_date),
          hub=nullif(trim(v_lot->>'hub'),''),custodian=nullif(trim(v_lot->>'custodian'),''),
          channel=nullif(trim(v_lot->>'channel'),''),is_pinned=(v_lot->>'pinned')::boolean,
          inventory_status=v_status,clearance_approved_at=v_clearance_at,
          clearance_approved_by=v_clearance_by,updated_at=now()
        where id=v_batch_id returning * into v_saved;
        insert into public.batch_change_events(batch_id,sku,reason,old_data,new_data,actor_id,created_at)
        values(v_saved.id,v_saved.sku,trim(v_payload->>'reason'),to_jsonb(v_existing),to_jsonb(v_saved),v_actor,v_instant) returning id into v_event_id;
    -- The approval/history event now exists. Finalize only this command's event.
    update public.product_batches set quantity_available=quantity_available
    where id=v_saved.id returning * into v_saved;
    update public.batch_change_events set new_data=to_jsonb(v_saved)
    where id=v_event_id;
      end if;
      v_count:=v_count+1;
    end loop;

    select coalesce(sum(b.quantity),0)::integer,
      coalesce(sum(greatest(b.quantity-b.reserved_quantity,0)) filter (where k2_private.lot_is_eligible_for_category_v1(b,v_depth,v_instant)),0)::integer
    into v_total,v_sellable from public.product_batches b where b.sku=trim(v_payload->>'sku');
    insert into public.inventory_balances(sku,location_code,on_hand)
    values(trim(v_payload->>'sku'),'MANILA_MAIN',v_total)
    on conflict(sku,location_code) do update set on_hand=excluded.on_hand,updated_at=now();
    perform set_config('k2.allow_stock_write','on',true);
    update public.products set stock_available=v_sellable,total_stock=v_sellable
    where sku=trim(v_payload->>'sku');
    v_result:=jsonb_build_object('sku',trim(v_payload->>'sku'),'updatedLots',v_count,
      'physicalQuantity',v_total,'sellableQuantity',v_sellable);

  else
    if (v_payload-array['batchId','approved','reason'])<>'{}'::jsonb
       or coalesce(v_payload->>'batchId','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       or jsonb_typeof(v_payload->'approved')<>'boolean'
       or length(trim(coalesce(v_payload->>'reason',''))) not between 10 and 500 then
      raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
    end if;
    -- K2_SIGNED_CLEARANCE_BALANCE_FIRST_V1
    -- Resolve without a lot lock, then recheck identity after canonical locks.
    select sku into v_clearance_sku from public.product_batches
    where id=(v_payload->>'batchId')::uuid;
    if not found then
      raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
    end if;
    insert into public.inventory_balances(sku,location_code,on_hand,reserved)
    select p.sku,'MANILA_MAIN',coalesce(sum(b.quantity),0)::integer,
      coalesce(sum(b.reserved_quantity),0)::integer
    from public.products p left join public.product_batches b on b.sku=p.sku
    where p.sku=v_clearance_sku group by p.sku
    on conflict(sku,location_code) do nothing;
    perform 1 from public.inventory_balances
    where sku=v_clearance_sku and location_code='MANILA_MAIN' for update;
    perform 1 from public.products where sku=v_clearance_sku for update;
    if not found then
      raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
    end if;
    perform 1 from public.product_batches where sku=v_clearance_sku order by id for update;
    select * into v_existing from public.product_batches
    where id=(v_payload->>'batchId')::uuid and sku=v_clearance_sku for update;
    if not found then
      raise exception using errcode='22023',message='K2_ADMIN_PAYLOAD_INVALID';
    end if;
    if (select k2_private.effective_category_minimum_v1(p.category_id,v_depth)
        from public.products p where p.sku=v_clearance_sku) is null then
     raise exception using errcode='23514',message='K2_CATEGORY_POLICY_TAXONOMY_INVALID';
    end if;
    v_instant:=k2_private.start_category_lot_context_v1(v_depth);
    v_today:=(v_instant at time zone 'Asia/Manila')::date;
    v_expiry:=coalesce(v_existing.expiry_date,v_existing.best_before_date);
    if (v_payload->>'approved')::boolean and (
      v_expiry is null or v_expiry<v_today+31 or v_expiry>v_today+89
      or v_existing.quantity<=0 or v_existing.inventory_status not in ('available','quarantine')
    ) then
      raise exception using errcode='23514',message='K2_CLEARANCE_INELIGIBLE';
    end if;
    update public.product_batches set
      clearance_approved_at=case when (v_payload->>'approved')::boolean then v_instant else null end,
      clearance_approved_by=case when (v_payload->>'approved')::boolean then v_actor else null end,
      inventory_status=case when (v_payload->>'approved')::boolean then 'available' else 'quarantine' end,
      quantity_available=case when (v_payload->>'approved')::boolean
        then greatest(quantity-reserved_quantity,0) else 0 end,
      updated_at=now()
    where id=v_existing.id returning * into v_saved;
    insert into public.batch_change_events(batch_id,sku,reason,old_data,new_data,actor_id,created_at)
    values(v_saved.id,v_saved.sku,trim(v_payload->>'reason'),to_jsonb(v_existing),to_jsonb(v_saved),v_actor,v_instant) returning id into v_event_id;
    -- The approval/history event now exists. Finalize only this command's event.
    update public.product_batches set quantity_available=quantity_available
    where id=v_saved.id returning * into v_saved;
    update public.batch_change_events set new_data=to_jsonb(v_saved)
    where id=v_event_id;
    select coalesce(sum(greatest(b.quantity-b.reserved_quantity,0)),0)::integer into v_sellable
    from public.product_batches b where b.sku=v_saved.sku and k2_private.lot_is_eligible_for_category_v1(b,v_depth,v_instant);
    perform set_config('k2.allow_stock_write','on',true);
    update public.products set stock_available=v_sellable,total_stock=v_sellable where sku=v_saved.sku;
    v_result:=jsonb_build_object('batchId',v_saved.id,'sku',v_saved.sku,
      'approved',(v_payload->>'approved')::boolean,'inventoryStatus',v_saved.inventory_status,
      'quantityAvailable',v_saved.quantity_available,'sellableQuantity',v_sellable);
  end if;

  update k2_private.admin_command_receipts set result=v_result,completed_at=now()
  where actor_id=v_actor and action=p_action and idempotency_key=p_idempotency_key;
  perform k2_private.clear_category_lot_context_v1();
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.execute_admin_product_family_v1(p_action text, p_timestamp bigint, p_nonce uuid, p_idempotency_key uuid, p_payload_text text, p_signature text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare
  v_actor uuid:=auth.uid();
  v_payload jsonb;
  v_hash text;
  v_receipt k2_private.admin_command_receipts;
  v_id uuid;
  v_expected integer;
  v_version integer;
  v_name text;
  v_axes text[];
  v_skus text[];
  v_member jsonb;
  v_axis text;
  v_value text;
  v_product uuid;
  v_combination jsonb;
  v_before jsonb;
  v_after jsonb;
  v_result jsonb;
begin
  if v_actor is null or not coalesce(public.is_admin(),false) or coalesce(auth.jwt()->>'aal','')<>'aal2' then raise exception 'K2_FAMILY_ADMIN_REQUIRED'; end if;
  if p_action is distinct from 'product_family_save' or not coalesce(k2_private.verify_admin_bff_request(p_action,p_timestamp,p_nonce,p_idempotency_key,p_payload_text,p_signature),false) then
    raise exception 'K2_ADMIN_REQUEST_REPLAYED';
  end if;
  -- Low-volume staff grouping shares one lock before product locks or receipts.
  -- This also serializes simultaneous claims of the same ungrouped SKU.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('k2-product-families-v1',0));
  v_hash:=encode(extensions.digest(convert_to(p_payload_text,'UTF8'),'sha256'),'hex');
  select * into v_receipt from k2_private.admin_command_receipts where actor_id=v_actor and action=p_action and idempotency_key=p_idempotency_key;
  if found then
    if v_receipt.payload_hash is distinct from v_hash then raise exception 'K2_ADMIN_IDEMPOTENCY_CONFLICT'; end if;
    if v_receipt.result is null then raise exception 'K2_ADMIN_COMMAND_IN_PROGRESS'; end if;
    return v_receipt.result;
  end if;
  v_payload:=p_payload_text::jsonb;
  if octet_length(p_payload_text)>16000 or jsonb_typeof(v_payload) is distinct from 'object'
    or (v_payload-array['familyId','expectedVersion','name','axes','members'])<>'{}'::jsonb
    or not (v_payload ?& array['familyId','expectedVersion','name','axes','members'])
    or jsonb_typeof(v_payload->'axes') is distinct from 'array' or jsonb_typeof(v_payload->'members') is distinct from 'array'
    or jsonb_typeof(v_payload->'name') is distinct from 'string' or jsonb_typeof(v_payload->'familyId') is distinct from 'string'
    or jsonb_typeof(v_payload->'expectedVersion') is distinct from 'number'
    or coalesce(v_payload->>'expectedVersion','') !~ '^(0|[1-9][0-9]{0,9})$' then raise exception 'K2_FAMILY_INVALID'; end if;
  if (v_payload->>'expectedVersion')::bigint>2147483646 then raise exception 'K2_FAMILY_INVALID'; end if;
  v_expected:=(v_payload->>'expectedVersion')::integer;
  begin v_id:=(v_payload->>'familyId')::uuid; exception when invalid_text_representation then raise exception 'K2_FAMILY_INVALID'; end;
  v_name:=v_payload->>'name';
  if v_id is null or char_length(v_name) not between 1 and 120 or v_name<>btrim(v_name) or v_name<>normalize(v_name,NFC) or v_name~'[[:cntrl:]]' then raise exception 'K2_FAMILY_INVALID'; end if;
  if jsonb_array_length(v_payload->'axes')>6 or jsonb_array_length(v_payload->'members')>100 then raise exception 'K2_FAMILY_INVALID'; end if;
  if exists(select 1 from jsonb_array_elements(v_payload->'axes') x where jsonb_typeof(x)<>'string') then raise exception 'K2_FAMILY_INVALID'; end if;
  select coalesce(array_agg(x),'{}'::text[]) into v_axes from jsonb_array_elements_text(v_payload->'axes') x;
  if exists(select 1 from unnest(v_axes) x where char_length(x) not between 1 and 40 or x<>btrim(x) or x<>normalize(x,NFC) or x~'[[:cntrl:]]')
    or (select count(distinct lower(x)) from unnest(v_axes) x)<>cardinality(v_axes)
    or (jsonb_array_length(v_payload->'members')>0 and cardinality(v_axes)=0) then raise exception 'K2_FAMILY_INVALID'; end if;
  select coalesce(array_agg(x->>'sku'),'{}'::text[]) into v_skus from jsonb_array_elements(v_payload->'members') x;
  if exists(select 1 from unnest(v_skus) x where x is null or x!~'^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$')
    or (select count(distinct x) from unnest(v_skus) x)<>cardinality(v_skus) then raise exception 'K2_FAMILY_INVALID'; end if;
  select version into v_version from public.product_families where id=v_id;
  if coalesce(v_version,0)<>v_expected then raise exception 'K2_FAMILY_VERSION_CONFLICT'; end if;
  perform 1 from public.products p where p.sku=any(v_skus) or p.id in(select product_id from public.product_family_members where family_id=v_id) order by p.id for share;
  if (select count(*) from public.products where sku=any(v_skus))<>cardinality(v_skus) then raise exception 'K2_FAMILY_PRODUCT_MISSING'; end if;
  if (select count(distinct (brand_id,category_id)) from public.products where sku=any(v_skus))>1 then raise exception 'K2_FAMILY_TAXONOMY'; end if;
  if exists(select 1 from public.product_family_members m join public.products p on p.id=m.product_id where p.sku=any(v_skus) and m.family_id<>v_id) then raise exception 'K2_FAMILY_MEMBERSHIP_CONFLICT'; end if;
  v_before:=public.read_admin_product_families_v1('{}',v_id)->'family';
  insert into public.product_families(id,name,axes,version) values(v_id,v_name,v_axes,1)
  on conflict(id) do update set name=excluded.name,axes=excluded.axes,version=product_families.version+1,updated_at=now();
  delete from public.product_family_members where family_id=v_id;
  for v_member in select * from jsonb_array_elements(v_payload->'members') loop
    if jsonb_typeof(v_member) is distinct from 'object' or not(v_member ?& array['sku','options']) or (v_member-array['sku','options'])<>'{}'::jsonb
      or jsonb_typeof(v_member->'sku') is distinct from 'string' or jsonb_typeof(v_member->'options') is distinct from 'object' then raise exception 'K2_FAMILY_INVALID'; end if;
    if (select count(*) from jsonb_object_keys(v_member->'options'))<>cardinality(v_axes) or not((v_member->'options') ?& v_axes) then raise exception 'K2_FAMILY_INVALID'; end if;
    v_combination:='[]'::jsonb;
    foreach v_axis in array v_axes loop
      v_value:=v_member->'options'->>v_axis;
      if jsonb_typeof(v_member->'options'->v_axis) is distinct from 'string' or char_length(v_value) not between 1 and 80
        or v_value<>btrim(v_value) or v_value<>normalize(v_value,NFC) or v_value~'[[:cntrl:]]' then raise exception 'K2_FAMILY_INVALID'; end if;
      if exists(select 1 from public.product_family_members m where m.family_id=v_id and lower(m.options->>v_axis)=lower(v_value) and m.options->>v_axis<>v_value) then raise exception 'K2_FAMILY_INVALID'; end if;
      v_combination:=v_combination || jsonb_build_array(lower(v_value));
    end loop;
    if exists(select 1 from public.product_family_members where family_id=v_id and combination_key=v_combination) then raise exception 'K2_FAMILY_INVALID'; end if;
    select id into strict v_product from public.products where sku=v_member->>'sku';
    insert into public.product_family_members(product_id,family_id,options,combination_key) values(v_product,v_id,v_member->'options',v_combination);
  end loop;
  v_after:=public.read_admin_product_families_v1('{}',v_id)->'family';
  insert into k2_private.product_family_events(family_id,actor_id,before_state,after_state) values(v_id,v_actor,v_before,v_after);
  v_result:=jsonb_build_object('familyId',v_id,'version',v_expected+1,'memberCount',cardinality(v_skus));
  insert into k2_private.admin_command_receipts(actor_id,action,idempotency_key,payload_hash,result,completed_at) values(v_actor,p_action,p_idempotency_key,v_hash,v_result,now());
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.execute_admin_product_master_command_v1(p_action text, p_timestamp bigint, p_nonce uuid, p_idempotency_key uuid, p_payload_text text, p_signature text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=auth.uid(); v_payload jsonb; v_patch jsonb; v_hash text; v_reason text;
  v_existing k2_private.admin_command_receipts; v_result jsonb;
  v_count integer; v_inserted integer; v_product public.products%rowtype;
  v_next public.products%rowtype; v_sku text; v_target text; v_skus text[];
  v_before jsonb; v_after jsonb; v_item text;
  v_identity_lock bigint;
  v_allowed text[]:=array[
    'name','short','barcode','subcategory','country_of_origin','origin','net_weight','brand_id','category_id',
    'package_type','size','description','why_buy','why_rare','usage_instructions',
    'storage_instructions','ingredients','allergens','finished_product_details',
    'pairings','cost_price','srp','wholesale_price','dealer_price','reorder_level',
    'slug','seo_keywords','is_featured','is_human_reviewed','product_video_url','internal_notes'
  ];
begin
  if p_action not in ('product_master_update','product_master_status','product_master_delete','category_policy_set','category_policy_clear')
     or not public.is_admin() or coalesce(auth.jwt()->>'aal','')<>'aal2' then
    raise exception using errcode='42501',message='K2_ADMIN_REQUIRED';
  end if;
  if not k2_private.verify_admin_bff_request(
    p_action,p_timestamp,p_nonce,p_idempotency_key,p_payload_text,p_signature
  ) then raise exception using errcode='28000',message='K2_ADMIN_REQUEST_REPLAYED'; end if;
  v_payload:=p_payload_text::jsonb;
  if jsonb_typeof(v_payload)<>'object' or not (v_payload ? 'reason') then
    raise exception using errcode='22023',message='K2_ADMIN_PRODUCT_INVALID';
  end if;
  v_reason:=trim(v_payload->>'reason');
  if length(v_reason) not between 8 and 500 then
    raise exception using errcode='22023',message='K2_ADMIN_PRODUCT_REASON_INVALID';
  end if;
  v_hash:=encode(extensions.digest(convert_to(p_payload_text,'UTF8'),'sha256'),'hex');
  select * into v_existing from k2_private.admin_command_receipts
  where actor_id=v_actor and action=p_action and idempotency_key=p_idempotency_key;
  if found then
    if v_existing.payload_hash<>v_hash then raise exception using errcode='22023',message='K2_ADMIN_IDEMPOTENCY_CONFLICT'; end if;
    if v_existing.result is null then raise exception using errcode='55000',message='K2_ADMIN_COMMAND_IN_PROGRESS'; end if;
    return v_existing.result;
  end if;
  select count(*)::integer into v_count from k2_private.admin_command_receipts
  where actor_id=v_actor and action=p_action and created_at>now()-interval '1 minute';
  if v_count>=10 then raise exception using errcode='54000',message='K2_ADMIN_RATE_LIMITED'; end if;
  insert into k2_private.admin_command_receipts(actor_id,action,idempotency_key,payload_hash)
  values(v_actor,p_action,p_idempotency_key,v_hash) on conflict do nothing;
  get diagnostics v_inserted=row_count;
  if v_inserted=0 then raise exception using errcode='55000',message='K2_ADMIN_COMMAND_IN_PROGRESS'; end if;

  if p_action in ('category_policy_set','category_policy_clear') then
    v_result:=k2_private.execute_category_policy_payload_v1(p_action,v_payload);
  elsif p_action='product_master_update' then
    if not (v_payload ?& array['sku','patch','expectedUpdatedAt','reason'])
       or (v_payload-array['sku','patch','expectedUpdatedAt','reason'])<>'{}'::jsonb then
      raise exception using errcode='22023',message='K2_ADMIN_PRODUCT_INVALID';
    end if;
    v_sku:=trim(v_payload->>'sku'); v_patch:=v_payload->'patch';
    if v_sku!~'^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$' or jsonb_typeof(v_patch)<>'object'
       or v_patch='{}'::jsonb or exists(select 1 from jsonb_object_keys(v_patch) k where not (k=any(v_allowed))) then
      raise exception using errcode='22023',message='K2_ADMIN_PRODUCT_INVALID';
    end if;
    select * into v_product from public.products where sku=v_sku for update;
    if not found then raise exception using errcode='P0002',message='K2_PRODUCT_NOT_FOUND'; end if;
    if v_product.updated_at is distinct from (v_payload->>'expectedUpdatedAt')::timestamptz then
      raise exception using errcode='P0001',message='K2_ADMIN_PRODUCT_VERSION_CONFLICT';
    end if;
    if v_patch ? 'brand_id' or v_patch ? 'category_id' then
      if not (v_patch ?& array['brand_id','category_id'])
         or jsonb_typeof(v_patch->'brand_id') is distinct from 'string'
         or jsonb_typeof(v_patch->'category_id') is distinct from 'string' then
        raise exception using errcode='22023',message='K2_ADMIN_PRODUCT_INVALID';
      end if;
      if (v_product.status is distinct from 'Draft' or v_product.published is distinct from false
          or v_product.brand_id is not null and v_product.brand_id is distinct from (v_patch->>'brand_id')::uuid
          or v_product.category_id is not null and v_product.category_id is distinct from (v_patch->>'category_id')::uuid
          or v_product.brand_id is not null and v_product.category_id is not null
          or v_product.stock_available is distinct from 0 or v_product.total_stock is distinct from 0
          or exists(select 1 from public.product_batches b where b.sku=v_sku)
          or exists(select 1 from public.inventory_balances b where b.sku=v_sku and (
            b.on_hand is distinct from 0 or b.reserved is distinct from 0 or b.in_transit is distinct from 0
            or b.damaged is distinct from 0 or b.expired is distinct from 0 or b.unaccounted is distinct from 0))
          or exists(select 1 from public.inventory_events e where e.sku=v_sku)) then
        raise exception using errcode='23514',message='K2_PRODUCT_TAXONOMY_INITIAL_ONLY';
      end if;
    end if;
    v_next:=jsonb_populate_record(v_product,v_patch);
    if nullif(trim(v_next.name),'') is null or length(v_next.name)>240
       or length(coalesce(v_next.barcode,''))>64 or length(coalesce(v_next.short,''))>500
       or length(coalesce(v_next.subcategory,''))>120 or length(coalesce(v_next.country_of_origin,''))>120
       or length(coalesce(v_next.origin,''))>240 or length(coalesce(v_next.package_type,''))>120
       or length(coalesce(v_next.size,''))>120 or length(coalesce(v_next.slug,''))>180
       or length(coalesce(v_next.description,''))>10000 or length(coalesce(v_next.why_buy,''))>2000
       or length(coalesce(v_next.why_rare,''))>2000 or length(coalesce(v_next.usage_instructions,''))>5000
       or length(coalesce(v_next.storage_instructions,''))>5000 or length(coalesce(v_next.ingredients,''))>10000
       or length(coalesce(v_next.allergens,''))>5000 or length(coalesce(v_next.finished_product_details,''))>5000
       or length(coalesce(v_next.product_video_url,''))>2000 or length(coalesce(v_next.internal_notes,''))>5000
       or coalesce(v_next.net_weight,0)<0 or coalesce(v_next.net_weight,0)>100000
       or coalesce(v_next.cost_price,0)<0 or coalesce(v_next.cost_price,0)>1000000
       or coalesce(v_next.srp,0)<0 or coalesce(v_next.srp,0)>1000000
       or coalesce(v_next.wholesale_price,0)<0 or coalesce(v_next.wholesale_price,0)>1000000
       or coalesce(v_next.dealer_price,0)<0 or coalesce(v_next.dealer_price,0)>1000000
       or coalesce(v_next.reorder_level,0)<0 or coalesce(v_next.reorder_level,0)>1000000
       or coalesce(cardinality(v_next.pairings),0)>20 or coalesce(cardinality(v_next.seo_keywords),0)>30 then
      raise exception using errcode='22023',message='K2_ADMIN_PRODUCT_INVALID';
    end if;
    foreach v_item in array coalesce(v_next.pairings,'{}'::text[]) loop
      if length(v_item)>240 then raise exception using errcode='22023',message='K2_ADMIN_PRODUCT_INVALID'; end if;
    end loop;
    foreach v_item in array coalesce(v_next.seo_keywords,'{}'::text[]) loop
      if length(v_item)>120 then raise exception using errcode='22023',message='K2_ADMIN_PRODUCT_INVALID'; end if;
    end loop;
    -- Cooperate with fresh Draft admission; retain authorized master edit semantics.
    for v_identity_lock in
      select distinct identity_key from (values
        (case when v_next.name is distinct from v_product.name
          then pg_catalog.hashtextextended('k2.draft.name:' || lower(trim(v_next.name)), 0)
          else null::bigint end),
        (case when v_next.barcode is distinct from v_product.barcode
          and nullif(trim(v_next.barcode),'') is not null
          then pg_catalog.hashtextextended('k2.draft.barcode:' || lower(trim(v_next.barcode)), 0)
          else null::bigint end)
      ) identities(identity_key) where identity_key is not null order by identity_key
    loop
      perform pg_catalog.pg_advisory_xact_lock(v_identity_lock);
    end loop;

    v_before:=to_jsonb(v_product);
    update public.products set
      name=v_next.name,short=v_next.short,barcode=v_next.barcode,subcategory=v_next.subcategory,
      country_of_origin=v_next.country_of_origin,origin=v_next.origin,net_weight=v_next.net_weight,
      brand_id=v_next.brand_id,category_id=v_next.category_id,
      package_type=v_next.package_type,size=v_next.size,description=v_next.description,
      why_buy=v_next.why_buy,why_rare=v_next.why_rare,usage_instructions=v_next.usage_instructions,
      storage_instructions=v_next.storage_instructions,ingredients=v_next.ingredients,
      allergens=v_next.allergens,finished_product_details=v_next.finished_product_details,
      pairings=v_next.pairings,cost_price=v_next.cost_price,srp=v_next.srp,
      wholesale_price=v_next.wholesale_price,dealer_price=v_next.dealer_price,
      reorder_level=v_next.reorder_level,slug=v_next.slug,seo_keywords=v_next.seo_keywords,
      is_featured=v_next.is_featured,is_human_reviewed=v_next.is_human_reviewed,
      product_video_url=v_next.product_video_url,internal_notes=v_next.internal_notes,
      updated_at=clock_timestamp()
    where id=v_product.id returning * into v_next;
    v_after:=to_jsonb(v_next);
    insert into k2_private.product_master_events(actor_id,action,request_id,sku,reason,before_state,after_state)
    values(v_actor,p_action,p_idempotency_key,v_sku,v_reason,v_before,v_after);
    v_result:=jsonb_build_object('sku',v_sku,'status',v_next.status,'updatedAt',v_next.updated_at);

  elsif p_action='product_master_status' then
    if not (v_payload ?& array['skus','status','reason'])
       or (v_payload-array['skus','status','reason'])<>'{}'::jsonb
       or jsonb_typeof(v_payload->'skus')<>'array' then
      raise exception using errcode='22023',message='K2_ADMIN_PRODUCT_INVALID';
    end if;
    select array_agg(value order by value) into v_skus from jsonb_array_elements_text(v_payload->'skus');
    if cardinality(v_skus) not between 1 and 25 or cardinality(v_skus)<>cardinality(array(select distinct unnest(v_skus)))
       or exists(select 1 from unnest(v_skus) s where s!~'^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$') then
      raise exception using errcode='22023',message='K2_ADMIN_PRODUCT_INVALID';
    end if;
    v_target:=v_payload->>'status';
    if v_target not in ('Draft','Under Review','Live','Unlisted','Discontinued') then
      raise exception using errcode='22023',message='K2_PUBLICATION_STATUS_INVALID';
    end if;
    foreach v_sku in array v_skus loop
      select * into v_product from public.products where sku=v_sku for update;
      if not found then raise exception using errcode='P0002',message='K2_PRODUCT_NOT_FOUND'; end if;
      if (v_product.status,v_target) not in (
        ('Draft','Draft'),('Draft','Under Review'),('Under Review','Under Review'),
        ('Under Review','Draft'),('Under Review','Live'),('Under Review','Unlisted'),
        ('Live','Live'),('Live','Unlisted'),('Live','Discontinued'),
        ('Unlisted','Unlisted'),('Unlisted','Under Review'),('Unlisted','Discontinued'),
        ('Discontinued','Discontinued')
      ) then raise exception using errcode='23514',message='K2_PUBLICATION_TRANSITION_INVALID'; end if;
      if v_target='Live' and (
        nullif(trim(v_product.name),'') is null or v_product.brand_id is null or v_product.category_id is null
        or coalesce(v_product.srp,v_product.retail_price,0)<=0
        or nullif(trim(v_product.primary_image_url),'') is null
        or not coalesce(v_product.is_human_reviewed,false)
      ) then raise exception using errcode='23514',message='K2_PUBLICATION_NOT_READY'; end if;
      v_before:=jsonb_build_object('status',v_product.status,'published',v_product.published);
      update public.products set status=v_target,updated_at=clock_timestamp()
      where id=v_product.id returning * into v_next;
      v_after:=jsonb_build_object('status',v_next.status,'published',v_next.published);
      insert into k2_private.product_master_events(actor_id,action,request_id,sku,reason,before_state,after_state)
      values(v_actor,p_action,p_idempotency_key,v_sku,v_reason,v_before,v_after);
    end loop;
    v_result:=jsonb_build_object('skus',to_jsonb(v_skus),'status',v_target,'updated',cardinality(v_skus));

  else
    if not (v_payload ?& array['skus','pin','reason'])
       or (v_payload-array['skus','pin','reason'])<>'{}'::jsonb
       or jsonb_typeof(v_payload->'skus')<>'array' or (v_payload->>'pin')!~'^[0-9]{4}$' then
      raise exception using errcode='22023',message='K2_ADMIN_PRODUCT_INVALID';
    end if;
    select array_agg(value order by value) into v_skus from jsonb_array_elements_text(v_payload->'skus');
    if cardinality(v_skus) not between 1 and 25 or cardinality(v_skus)<>cardinality(array(select distinct unnest(v_skus)))
       or exists(select 1 from unnest(v_skus) s where s!~'^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$') then
      raise exception using errcode='22023',message='K2_ADMIN_PRODUCT_INVALID';
    end if;
    v_result:=public.delete_products_with_pin_v2(v_skus,v_payload->>'pin',v_reason,p_idempotency_key);
  end if;

  update k2_private.admin_command_receipts set result=v_result,completed_at=clock_timestamp()
  where actor_id=v_actor and action=p_action and idempotency_key=p_idempotency_key;
  return v_result;
exception when invalid_text_representation or numeric_value_out_of_range or datetime_field_overflow then
  raise exception using errcode='22023',message='K2_ADMIN_PRODUCT_INVALID';
end;
$function$

CREATE OR REPLACE FUNCTION public.read_admin_product_stock_v1(p_skus text[])
 RETURNS TABLE(sku text, stock_from_batches bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_depth integer; v_instant timestamptz:=pg_catalog.statement_timestamp();
begin
 if auth.uid() is null or not coalesce(public.is_staff(),false)
  or coalesce(auth.jwt()->>'aal','')<>'aal2' then
  raise exception using errcode='42501',message='K2_ADMIN_REQUIRED';
 end if;
 if p_skus is null or pg_catalog.cardinality(p_skus)>500
  or pg_catalog.array_ndims(p_skus)>1
  or exists(select 1 from pg_catalog.unnest(p_skus) s(value)
   where s.value is null or pg_catalog.length(s.value)>120
    or pg_catalog.btrim(s.value)='')
  or (select count(*) from pg_catalog.unnest(p_skus))
     <> (select count(distinct s.value) from pg_catalog.unnest(p_skus) s(value)) then
  raise exception using errcode='22023',message='K2_ADMIN_STOCK_READ_INVALID';
 end if;
 select c.maximum_depth into v_depth from k2_private.category_policy_command_config c where c.singleton;
 if v_depth is null or v_depth<1 then
  raise exception using errcode='55000',message='K2_CATEGORY_POLICY_NOT_CONFIGURED';
 end if;
 return query
 with staff_products as materialized (
  select p.sku,k2_private.effective_category_minimum_v1(p.category_id,v_depth) as minimum
  from public.products p where p.sku=any(p_skus)
 ), eligible_lots as materialized (
  select b.sku,(b.quantity-b.reserved_quantity)::bigint as units
  from public.product_batches b join staff_products p on p.sku=b.sku
  where b.reserved_quantity<b.quantity
   and k2_private.lot_is_eligible_for_minimum_v1(b,p.minimum,v_instant)
 )
 select p.sku::text,
  case when p.minimum is null and exists(
   select 1 from public.product_batches b where b.sku=p.sku and b.quantity>0
  ) then null::bigint else coalesce(pg_catalog.sum(e.units),0)::bigint end
 from staff_products p left join eligible_lots e on e.sku=p.sku
 group by p.sku,p.minimum order by p.sku;
end $function$

CREATE OR REPLACE FUNCTION public.reconcile_product_batches(p_sku text, p_batches jsonb, p_reason text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_payload jsonb;
  v_existing public.product_batches;
  v_saved public.product_batches;
  v_id uuid;
  v_qty integer;
  v_status text;
  v_expiry date;
  v_total integer;
  v_sellable integer;
  v_count integer := 0;
  v_depth integer;v_instant timestamptz;v_today date;
  v_context k2_private.category_lot_command_context;
  v_owned_context boolean:=false;v_event_id uuid;
begin
  if not public.is_staff() then raise exception 'Staff access required'; end if;
  if nullif(trim(coalesce(p_reason, '')), '') is null then raise exception 'A reconciliation reason is required'; end if;
  if jsonb_typeof(p_batches) <> 'array' or jsonb_array_length(p_batches) > 200 then raise exception 'Batches must be an array of at most 200 rows'; end if;
  perform k2_private.lock_category_policy_v1(false);
  select maximum_depth into v_depth from k2_private.category_policy_command_config where singleton;
  if v_depth is null or v_depth<1 then raise exception using errcode='55000',message='K2_CATEGORY_POLICY_NOT_CONFIGURED';end if;
  -- K2_RECONCILIATION_BALANCE_FIRST_V1
  -- Conflict checks also lock: take the balance before product/FK or lot locks.
  insert into public.inventory_balances(sku,location_code,on_hand,reserved)
  select p.sku,'MANILA_MAIN',coalesce(sum(b.quantity),0)::integer,
    coalesce(sum(b.reserved_quantity),0)::integer
  from public.products p left join public.product_batches b on b.sku=p.sku
  where p.sku=p_sku group by p.sku
  on conflict(sku,location_code) do nothing;
  perform 1 from public.inventory_balances where sku=p_sku and location_code='MANILA_MAIN' for update;
  perform 1 from public.products where sku = p_sku for update;
  if not found then raise exception 'Product not found'; end if;
  perform 1 from public.product_batches where sku=p_sku order by id for update;
  if (select k2_private.effective_category_minimum_v1(p.category_id,v_depth) from public.products p where p.sku=p_sku) is null then
    raise exception using errcode='23514',message='K2_CATEGORY_POLICY_TAXONOMY_INVALID';end if;
  if exists(select 1 from k2_private.category_lot_command_context where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then
    v_context:=k2_private.current_category_lot_context_v1();
    if v_context.maximum_depth<>v_depth then raise exception using errcode='55000',message='K2_CATEGORY_CONTEXT_DEPTH_MISMATCH';end if;
    v_instant:=v_context.evaluation_instant;
  else v_instant:=k2_private.start_category_lot_context_v1(v_depth);v_owned_context:=true;end if;
  v_today:=(v_instant at time zone 'Asia/Manila')::date;

  if exists (
    select 1 from public.product_batches b where b.sku = p_sku
      and not exists (
        select 1 from jsonb_array_elements(p_batches) x
        where nullif(x ->> 'id', '')::uuid = b.id
      )
  ) then raise exception 'Existing lots cannot be removed. Set the physical count to zero with a reason so history is preserved.'; end if;

  for v_payload in select * from jsonb_array_elements(p_batches)
  loop
    begin v_qty := coalesce((v_payload ->> 'quantity')::integer, 0);
    exception when invalid_text_representation then raise exception 'Batch quantity must be a whole number'; end;
    if v_qty < 0 then raise exception 'Batch quantity cannot be negative'; end if;
    v_expiry := nullif(v_payload ->> 'expiry_date', '')::date;
    v_status := coalesce(nullif(v_payload ->> 'inventory_status', ''),
      case when v_qty = 0 then 'depleted'
           when v_expiry is null or v_expiry <= v_today + 30 then 'quarantine'
           else 'available' end);
    if v_status not in ('available', 'quarantine', 'damaged', 'expired', 'unaccounted', 'depleted') then raise exception 'Invalid inventory status'; end if;
    if v_qty > 0 and nullif(trim(coalesce(v_payload ->> 'box_code', '')), '') is null then raise exception 'Every physical lot needs a box code'; end if;

    v_id := nullif(v_payload ->> 'id', '')::uuid;
    if v_id is null then
      insert into public.product_batches (
        sku, box_code, batch_code, quantity, quantity_available, reserved_quantity,
        expiry_date, best_before_date, landed_date, hub, custodian, channel,
        is_pinned, inventory_status, updated_at
      ) values (
        p_sku, nullif(trim(v_payload ->> 'box_code'), ''), nullif(trim(v_payload ->> 'batch_code'), ''),
        v_qty, v_qty, 0, v_expiry, v_expiry,
        coalesce(nullif(v_payload ->> 'landed_date', '')::date, v_today),
        nullif(trim(v_payload ->> 'hub'), ''), nullif(trim(v_payload ->> 'custodian'), ''),
        nullif(trim(v_payload ->> 'channel'), ''), coalesce((v_payload ->> 'is_pinned')::boolean, false),
        v_status, v_instant
      ) returning * into v_saved;
      insert into public.batch_change_events (batch_id, sku, reason, old_data, new_data, actor_id,created_at)
      values (v_saved.id, p_sku, trim(p_reason), null, to_jsonb(v_saved), auth.uid(),v_instant) returning id into v_event_id;
    else
      select * into v_existing from public.product_batches where id = v_id and sku = p_sku for update;
      if not found then raise exception 'Batch % does not belong to %', v_id, p_sku; end if;
      if v_qty < v_existing.reserved_quantity then raise exception 'Batch quantity cannot be lower than its reserved quantity'; end if;
      update public.product_batches set
        box_code = nullif(trim(v_payload ->> 'box_code'), ''),
        batch_code = coalesce(nullif(trim(v_payload ->> 'batch_code'), ''), nullif(trim(v_payload ->> 'box_code'), '')),
        quantity = v_qty, quantity_available = v_qty,
        expiry_date = v_expiry, best_before_date = v_expiry,
        landed_date = coalesce(nullif(v_payload ->> 'landed_date', '')::date, landed_date),
        hub = nullif(trim(v_payload ->> 'hub'), ''), custodian = nullif(trim(v_payload ->> 'custodian'), ''),
        channel = nullif(trim(v_payload ->> 'channel'), ''),
        is_pinned = coalesce((v_payload ->> 'is_pinned')::boolean, false),
        inventory_status = v_status, updated_at = v_instant
      where id = v_id returning * into v_saved;
      insert into public.batch_change_events (batch_id, sku, reason, old_data, new_data, actor_id,created_at)
      values (v_saved.id, p_sku, trim(p_reason), to_jsonb(v_existing), to_jsonb(v_saved), auth.uid(),v_instant) returning id into v_event_id;
    end if;
    -- Event insertion can invalidate an older clearance epoch; refresh afterward.
    update public.product_batches b set quantity_available=case when k2_private.lot_is_eligible_for_category_v1(b,v_depth,v_instant) then greatest(b.quantity-b.reserved_quantity,0) else 0 end
    where b.id=v_saved.id returning * into v_saved;
    update public.batch_change_events set new_data=to_jsonb(v_saved) where id=v_event_id;
    v_count := v_count + 1;
  end loop;

  select coalesce(sum(quantity), 0)::integer,
         coalesce(sum(quantity - reserved_quantity) filter (
           where k2_private.lot_is_eligible_for_category_v1(product_batches,v_depth,v_instant)
         ), 0)::integer
  into v_total, v_sellable from public.product_batches where sku = p_sku;

  insert into public.inventory_balances (sku, location_code, on_hand)
  values (p_sku, 'MANILA_MAIN', v_total)
  on conflict (sku, location_code) do update set on_hand = excluded.on_hand, updated_at = v_instant;
  perform set_config('k2.allow_stock_write', 'on', true);
  update public.products set stock_available = v_sellable, total_stock = v_sellable where sku = p_sku;
  if v_owned_context then perform k2_private.clear_category_lot_context_v1();end if;
  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION k2_private.lot_is_eligible_for_minimum_v1(p_lot product_batches, p_minimum integer, p_evaluation_instant timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare

 v_minimum integer:=p_minimum;
 v_expiry date:=coalesce(p_lot.expiry_date,p_lot.best_before_date);
 v_today date;
 v_days numeric;
begin
 if p_evaluation_instant is null or not pg_catalog.isfinite(p_evaluation_instant)
    or v_expiry is null or not pg_catalog.isfinite(v_expiry) then return false; end if;
 -- A finite timestamp near the type limit can still overflow during timezone conversion.
 begin
  v_today:=(p_evaluation_instant at time zone 'Asia/Manila')::date;
 exception when datetime_field_overflow then return false;
 end;
 if v_minimum is null or v_minimum<90 then return false; end if;
 -- Each finite date's epoch offset fits int; widen BEFORE subtracting offsets.
 -- This avoids adding a potentially int-max policy minimum to a near-limit date.
 v_days:=(v_expiry-date '2000-01-01')::numeric-(v_today-date '2000-01-01')::numeric;
 return exists (
  select 1 from public.hubs h
  join public.custodians c on c.id=p_lot.custodian and c.hub_id=h.id
  where h.id=p_lot.hub and h.id='HUB-MNL-CENTRAL' and h.country='PH'
   and p_lot.inventory_status='available' and p_lot.quantity>0
   and p_lot.reserved_quantity>=0 and p_lot.reserved_quantity<=p_lot.quantity
   and (
    v_days>=v_minimum
    or (
     v_days between 31 and 89
     and p_lot.clearance_approved_at is not null and p_lot.clearance_approved_by is not null
     and p_lot.clearance_approved_at<=p_evaluation_instant
     and exists (
      select 1 from public.batch_change_events e
      where e.batch_id=p_lot.id and e.sku=p_lot.sku and e.actor_id=p_lot.clearance_approved_by
       and nullif(pg_catalog.btrim(e.reason),'') is not null
       -- Preserve both supported approval writers and same-instant marker/event evidence.
       and e.created_at=p_lot.clearance_approved_at and e.created_at<=p_evaluation_instant
       and coalesce(e.new_data->>'expiry_date',e.new_data->>'best_before_date')=v_expiry::text
       and (
        e.new_data->'clearance_approved'='true'::jsonb
        or (e.new_data->>'clearance_approved_by'=p_lot.clearance_approved_by::text
         and case when pg_catalog.pg_input_is_valid(
          e.new_data->>'clearance_approved_at','timestamp with time zone')
          then (e.new_data->>'clearance_approved_at')::timestamptz end=p_lot.clearance_approved_at
         and e.old_data->'clearance_approved_at' is distinct from e.new_data->'clearance_approved_at')
       )
       and not exists (
        select 1 from public.batch_change_events x
        where x.batch_id=p_lot.id and x.sku=p_lot.sku and x.id<>e.id
         and x.created_at>=p_lot.clearance_approved_at and x.created_at<=p_evaluation_instant
         and (
          x.new_data->'clearance_approved'='false'::jsonb
          or (x.new_data ? 'inventory_status' and (
           x.new_data->>'inventory_status' is distinct from 'available'
           or x.old_data->'expiry_date' is distinct from x.new_data->'expiry_date'
           or x.old_data->'best_before_date' is distinct from x.new_data->'best_before_date'
          ))
         )
       )
     )
    )
   )
 );
end $function$

CREATE OR REPLACE FUNCTION k2_private.public_category_minimum_v1(p_category uuid)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 declare v_depth integer;v_minimum integer;
 begin
  select maximum_depth into v_depth from k2_private.category_policy_command_config where singleton;
  if v_depth is null or v_depth<1 then
   raise exception using errcode='55000',message='K2_CATEGORY_POLICY_NOT_CONFIGURED';
  end if;
  v_minimum:=k2_private.effective_category_minimum_v1(p_category,v_depth);
  if v_minimum is null then
   raise exception using errcode='23514',message='K2_CATEGORY_POLICY_TAXONOMY_INVALID';
  end if;
  return v_minimum;
 end $function$
